:root {
  /* Core Solid Color Palette - Strictly No Gradients */
  --bg-primary: #0C0D0E;
  --bg-secondary: #131517;
  --bg-tertiary: #1B1E21;
  --bg-card: #151719;
  --bg-card-hover: #1A1D20;
  --bg-overlay: rgba(12, 13, 14, 0.92);
  --bg-modal: #141618;

  /* Hairline Borders & Dividers */
  --border-subtle: #222529;
  --border-light: #2D3238;
  --border-accent: #C5A880;

  /* Typography Colors */
  --text-primary: #F4F1EA;
  --text-secondary: #9B9FA5;
  --text-muted: #6C7077;
  --text-inverted: #0C0D0E;

  /* Subtle Warm Accent (Solid Brass / Antique Gold) */
  --accent-gold: #C5A880;
  --accent-gold-hover: #D8BCA4;
  --accent-gold-dim: #26211B;
  --accent-gold-border: #3D352B;

  /* Status Solid Colors */
  --color-success: #2E7D32;
  --color-success-bg: #132415;
  --color-error: #D32F2F;
  --color-error-bg: #291212;

  /* Typography Tokens */
  --font-serif: 'Cormorant Garamond', Georgia, serif;
  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;

  /* Layout Spacing */
  --container-max: 1240px;
  --container-narrow: 860px;
  --header-height: 80px;

  /* Transitions */
  --transition-fast: 0.2s ease;
  --transition-base: 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  --transition-slow: 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

